package com.ntd.csdl;
import com.ntd.csdl.service.*;import com.ntd.csdl.entity.*;import com.ntd.csdl.dto.*;import com.ntd.csdl.repo.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
import java.util.*;import java.math.BigDecimal;import java.nio.file.*;
class PaymentRoutingTests {
 JdbcTemplate jdbc;PaymentRoutingService routing;PaymentReportService payments;PaymentReport legacy,normal;PaymentReportRepository reports;LandlordService owners;FinanceService finance;
 @BeforeEach void init() throws Exception {
  jdbc=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;NON_KEYWORDS=USER;DB_CLOSE_DELAY=-1","sa",""));jdbc.execute("CREATE TABLE user(id BIGINT PRIMARY KEY,username VARCHAR(100),role INT)");jdbc.execute("CREATE TABLE payment_reports(payment_report_id BIGINT PRIMARY KEY)");jdbc.update("INSERT INTO user VALUES(1,'ADMIN',1),(2,'B',1),(3,'ntd72',0)");jdbc.update("INSERT INTO payment_reports VALUES(11),(12)");
  String schema=Files.readString(Path.of("src/main/resources/schema.sql"));schema=schema.substring(schema.indexOf("CREATE TABLE IF NOT EXISTS payment_report_routes"));jdbc.execute(schema.replaceAll("ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci", "").replace(";",""));
  owners=mock(LandlordService.class);when(owners.owner("R1")).thenReturn(1L);when(owners.owner("LEGACY")).thenReturn(null);when(owners.owns("ADMIN","R1")).thenReturn(true);doAnswer(i->{String name=i.getArgument(0),room=i.getArgument(1);if(!("ADMIN".equals(name)&&"R1".equals(room)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Other owner");return null;}).when(owners).requireOwner(anyString(),anyString());
  User payer=new User();payer.setId(3L);payer.setUsername("ntd72");legacy=report(11L,"DM1","LEGACY",payer);normal=report(12L,"I2","R1",payer);reports=mock(PaymentReportRepository.class);when(reports.lockById(11L)).thenReturn(Optional.of(legacy));when(reports.lockById(12L)).thenReturn(Optional.of(normal));when(reports.findAllByOrderByCreatedAtDesc()).thenReturn(List.of(legacy,normal));when(reports.findByPayerUsernameOrderByCreatedAtDesc("ntd72")).thenReturn(List.of(legacy,normal));routing=new PaymentRoutingService(jdbc,owners,reports);finance=mock(FinanceService.class);payments=new PaymentReportService(reports,mock(InvoiceRepository.class),mock(UserRepository.class),mock(RentalWorkflowService.class),owners,finance,routing);
 }
 PaymentReport report(Long id,String invoice,String room,User payer){var p=new PaymentReport();p.setPaymentReportId(id);p.setPayer(payer);p.setAmount(new BigDecimal("2680000"));p.setInvoice(Invoice.builder().invoiceId(invoice).contract(Contract.builder().contractId("C"+id).room(Room.builder().roomId(room).build()).build()).build());return p;}
 @Test void missingOwnerIsVisibleToPayerButNotBroadcastToEveryAdmin(){var own=payments.getForAccount("ntd72",true);assertEquals("UNASSIGNED",own.getFirst().getRoutingStatus());assertEquals(1,payments.getForAccount("ADMIN",false).size());assertTrue(payments.getForAccount("B",false).isEmpty());}
 @Test void tenantCanDirectTheirLegacyReportToOneNamedLandlordWhoMustStillConfirm(){routing.assign("ntd72",11L,1L);assertEquals("ADMIN",payments.getForAccount("ntd72",true).getFirst().getLandlordName());assertEquals("LEGACY_ROUTED",payments.getForAccount("ntd72",true).getFirst().getRoutingStatus());assertEquals(2,payments.getForAccount("ADMIN",false).size());assertTrue(payments.getForAccount("B",false).isEmpty());assertEquals(PaymentReportStatus.PENDING,legacy.getStatus());var dto=new PaymentReportStatusDTO();dto.setStatus("PAID");payments.updateStatus(11L,dto,"ADMIN");verify(finance).confirmReceipt("ADMIN",legacy,null);assertEquals(PaymentReportStatus.PAID,legacy.getStatus());assertNull(owners.owner("LEGACY"));assertThrows(ResponseStatusException.class,()->routing.assign("ntd72",11L,2L));}
 @Test void normalInvoiceCannotBeRedirectedAndOnlyPayerCanRouteAnOrphan(){assertThrows(ResponseStatusException.class,()->routing.assign("ntd72",12L,2L));assertThrows(ResponseStatusException.class,()->routing.assign("another",11L,1L));assertThrows(ResponseStatusException.class,()->routing.assign("ntd72",11L,3L));assertFalse(routing.assignedTo("B",normal));assertTrue(routing.assignedTo("ADMIN",normal));}
 @Test void wrongAdminCannotConfirmAndChangingRecipientRevokesOldPendingAccess(){var dto=new PaymentReportStatusDTO();dto.setStatus("PAID");assertThrows(ResponseStatusException.class,()->payments.updateStatus(11L,dto,"ADMIN"));routing.assign("ntd72",11L,1L);routing.assign("ntd72",11L,2L);assertThrows(ResponseStatusException.class,()->payments.updateStatus(11L,dto,"ADMIN"));assertEquals(1,payments.getForAccount("B",false).size());verify(finance,never()).confirmReceipt(anyString(),any(),any());}
}
